pub fn pairwise_addition(a: Vec<i32>) -> Vec<i32> {
    // Since the length is guaranteed to be even, we can safely divide by 2.
    let n = a.len();
    assert!(n % 2 == 0, "Input vector must have even length");

    // Pre-allocate the result vector with the known capacity.
    let mut result = Vec::with_capacity(n / 2);

    // Step through the input in steps of 2 and sum each pair.
    for i in (0..n).step_by(2) {
        result.push(a[i] + a[i + 1]);
    }

    result
}

